HERE = os.path.dirname(os.path.abspath(__file__)); sys.path.insert(0, os.path.join(HERE, '..', '..')); sys.path.insert(0, os.path.join(HERE, '..', '..', '..', '..'))
import aeneid_lib as A
# aeneid-039 draft. Drafted from the Latin and grammar only. t is cut from the edition, never typed.
TITLE = 'Venus et Neptunus. Somnus. Palinurus'
TITLE_EN = "Venus and Neptune, the Sleep-god and Palinurus's Fall — Aeneid V.779–871"
PART = "Venus and Neptune, the Sleep-god and Palinurus's Fall (V.779–871)"
ABOUT = "With the fleet already under way from Sicily, Venus goes to Neptune in her anxiety and begs him to see her son safely to Italy: Juno's anger, she says, nothing will wear down, she stirred up the sea in Libya and drove the Trojan women to burn the ships. Neptune answers that she may trust his realm, as she could before: he once rescued Aeneas in a cloud when Achilles was driving the Trojans against their walls, and he will do it again. Aeneas will reach the harbour of Avernus unharmed; but one man will be lost in the flood, and one life will be given for many. He yokes his horses and skims over the water, the swell sinks, the clouds scatter, and a train of sea-creatures and sea-gods escorts the fleet. The crews trim the sails, and Palinurus leads the line. In the middle of the night, with the sailors asleep at their oars, the god Sleep glides down and, in the likeness of Phorbas, tells the helmsman to rest and let him take the tiller. Palinurus answers that he will not trust the calm sea, and clings to the rudder. Then the god shakes over his temples a branch dripping with the water of Lethe, and his eyes close; Sleep hurls him, with part of the stern and the helm, into the waves, and flies off into the air. The fleet runs on unharmed, under Neptune's pledge, till it comes near the rocks of the Sirens. There Aeneas feels the ship drifting with no helmsman, takes the steering himself, and with a groan for his friend's fate speaks his lament: Palinurus, too trusting in calm sky and sea, will lie naked on an unknown shore."
U = [
(780, 'questus:',
 'But Venus meanwhile, stirred up by cares, Neptune\naddresses, and pours out from her breast such complaints:',
 'But meanwhile Venus, tormented by her cares, goes to Neptune and speaks, pouring such complaints from her heart:',
 "A new paragraph. The Latin Library prints 'prosequitur surgens a puppi ventus euntis' (the wind rising astern) here, just before 'At Venus', and not at 777, where Greenough prints it, at the end of the last part; it is the same line in another place, and Greenough has nothing here. 'At' sets Venus against the departure just described; 'interea' is 'meanwhile'. 'Exercita' is the perfect participle passive of 'exerceo', 'worried', 'harassed', agreeing with Venus. 'Adloquitur' is Greenough's spelling of 'alloquitur', 'speaks to', with the accusative 'Neptunum'; 'tales… questus' is 'such complaints', the accusative plural of 'questus' (fourth declension), and the colon leads to her speech. The Latin Library prints 'talisque' for Greenough's 'talesque', the same accusative plural."),
(782, 'omnes;',
 "“Juno's heavy anger and her heart not to be sated\ncompel me, Neptune, to descend to all prayers;",
 "“Juno's grievous anger and her heart that nothing can sate drive me, Neptune, to go down to every kind of prayer;",
 "The opening mark begins Venus's speech, which runs to 798. 'Iunonis gravis ira' and 'exsaturabile pectus' are the two subjects, with 'cogunt' plural to match; 'gravis' agrees with 'ira' ('heavy', 'grievous'). 'Exsaturabile' is a verbal adjective in '-bilis', 'that can be sated', and 'nec' negates it, so 'nec exsaturabile pectus' is 'and a heart not to be sated' (the Latin Library prints 'neque' for Greenough's 'nec'). 'Me… descendere' is an accusative and infinitive after 'cogunt', 'compel me to descend', 'in omnes preces' meaning to stoop to every kind of entreaty, even this one. 'Omnes' is the accusative plural in '-es' (the Latin Library prints 'omnis'); the form is the same case."),
(784, 'quiescit.',
 "whom neither long time, nor any piety, softens,\nnor by Jupiter's command and by the fates broken is she quiet.",
 "Juno, whom neither the long years nor any piety can soften, and who, curbed by Jupiter's command and the fates, still does not grow quiet.",
 "'Quam' is a connecting relative looking back to Juno (or to her 'ira'); either way it is accusative feminine singular, the object of 'mitigat'. 'Mitigat' is singular though it has two subjects, 'dies' and 'pietas', the verb agreeing with the nearer; 'ulla' goes with 'pietas', 'any piety'. 'Dies' is feminine here, as often, for a length of time. 'Imperio fatisque' are ablatives of means or cause, 'by Jupiter's command and the fates'; 'infracta' is the perfect participle passive of 'infringo', 'broken', 'curbed', nominative feminine, agreeing with the subject of 'quiescit' (Juno, or her anger: the Latin does not say which). She does not rest even when the fates and Jupiter have said that Aeneas will found Rome."),
(786, 'omnem:',
 'Not from the midst of the people of the Phrygians to have devoured\nthe city with unspeakable hatreds is enough, nor to have dragged through every punishment:',
 'It is not enough for her to have eaten a city out of the heart of the Phrygian nation with her unspeakable hatred, nor to have dragged them through the whole of their punishment:',
 "'Non… satis est' is 'it is not enough', followed by two perfect infinitives, 'exedisse' ('to have eaten out', 'devoured') and 'traxe', the contracted form of 'traxisse' (you'll see such forms constantly). 'De media gente Phrygum' is 'from the midst of the Phrygian people', 'Phrygum' the old genitive plural in '-um' (you'll see this constantly); the Phrygians are Trojans, from Phrygia in Asia Minor. 'Nefandis odiis' is an ablative of means, 'with unspeakable hatreds', 'nefandus' meaning what may not be said. 'Poenam… per omnem' is 'through every punishment', the noun placed before the verb and 'per' after it with its adjective ('per omnem poenam'); the object of 'traxe', 'them' (the Trojans), is left unexpressed. The colon leads to the further charge."),
(788, 'insequitur:',
 'the remains of Troy, the ashes and bones of her who is destroyed\nshe pursues:',
 'the survivors of Troy, the ashes and bones of a city destroyed, she hounds:',
 "'Reliquias Troiae' is 'the remnants of Troy', the survivors, and 'cineres atque ossa' 'the ashes and the bones' is in apposition to it: the survivors are called the ashes and bones of the dead city. 'Peremptae' is the perfect participle passive of 'perimo', 'destroyed', genitive feminine, agreeing with 'Troiae'. 'Insequitur' is a deponent, 'pursues', its object the remnants, ashes and bones. The colon sets up the sarcastic clause that follows."),
(788, 'furoris.',
 'the causes of so great a fury let her know.',
 'Let her be the one to know the causes of so great a rage.',
 "'Sciat' is a present subjunctive of command, a jussive, 'let her know', and sharp with irony: Venus challenges Juno to produce a reason for her fury, and implies that none exists. 'Illa' is Juno, 'that one', with no name; 'tanti… furoris' 'of so great a madness' is a genitive after 'causas'. The sentence begins in the middle of 788, after the colon."),
(790, 'excierit:',
 'You yourself lately to me are witness in the Libyan waves\nwhat a mass she suddenly stirred up:',
 'You yourself, lately, in the Libyan waves, were my witness to what a mass of storm she suddenly raised:',
 "'Ipse… tu testis' is 'you yourself (are) a witness', with 'es' left out; 'mihi' is a dative of reference, 'for me', 'on my behalf', and 'nuper' 'lately', for the storm of Book I that drove the fleet to Carthage (Aeolus sent it at Juno's request). 'Quam molem… excierit' is an indirect question after 'testis', 'what a mass she stirred up', 'excierit' a perfect subjunctive, 'moles' the heaped mass of water and wind. 'Libycis' is the adjective for 'Libyan', Africa. The colon leads to what she did."),
(792, 'tuis.',
 'all the seas with the sky\nshe mingled, on Aeolian storms in vain relying,\nin your realms this having dared.',
 'She mixed all the seas with the sky, relying in vain on the Aeolian storms, daring this in your own kingdoms.',
 "A half-line: Virgil left this verse unfinished (one of the 'hemistichs', about 58 in the poem), and Greenough prints it short, ending at 'tuis'. 'Maria omnia caelo miscuit' is 'mixed all the seas with the sky'. 'Aeoliis… procellis' is an ablative of means with 'freta' (from 'fretus', 'relying on'), 'freta' nominative feminine agreeing with Juno, 'relying on' taking the ablative. 'Nequiquam' is 'in vain'. 'Ausa' is the perfect participle of the semi-deponent 'audeo', 'having dared', with active sense; 'in regnis… tuis' is the offence, 'hoc', 'this', done in Neptune's own domain."),
(795, 'terrae.',
 'Through wickedness, look, even the Trojan mothers having been driven,\nshe burned foully the ships, and with the fleet\nlost forced (him) the comrades to leave to an unknown land.',
 'See, by crime she has even driven the Trojan mothers on, burned the ships foully, and, the fleet lost, forced him to leave his comrades behind in an unknown land.',
 "'Per scelus' is 'by crime', 'through wickedness'; 'ecce' is 'look'. 'Matribus… actis' is an ablative absolute, 'the mothers having been driven' (to crime, as Iris drove them in V.604ff). 'Exussit' is the perfect of 'exuro', 'burned up'; 'foede' 'foully'; Greenough's 'puppes' is the accusative plural (the Latin Library prints 'puppis', the same case). 'Classe… amissa' is an ablative absolute, 'the fleet having been lost'. 'Subegit' is 'forced', 'compelled', and takes an infinitive; its object, Aeneas, is left unexpressed, and 'socios' is the object of 'linquere': 'forced (him) to leave his comrades'. 'Ignotae terrae' is a dative, 'to an unknown land' (Sicily): after the fire, those who could not sail had to be left there (V.746ff)."),
(797, 'Thybrim:',
 'For what remains, I ask, may it be permitted to give safe through the waves\nsails to you, may it be permitted to reach the Laurentian Tiber:',
 'For the rest, I beg: let him be allowed to set his sails safely across the waves in your keeping, let him be allowed to reach the Laurentian Tiber:',
 "'Quod superest' is 'as for what remains', 'for the rest', an adverbial accusative. 'Liceat' is a present subjunctive, 'may it be allowed', repeated at the start of the next clause (anaphora) for emphasis; the person allowed (Aeneas) is not named. 'Dare… vela… tibi' is 'to give his sails to you': 'vela dare' alone is the idiom for setting sail, and 'tibi' is Neptune, to whose care they are entrusted; 'tuta' agrees with 'vela' ('safe') and 'per undas' is 'over the waves'. 'Laurentem… Thybrim' is the Tiber of Laurentum, the coastal region of Latium, 'Thybrim' an accusative in '-im'. The colon is followed by a condition."),
(798, 'Parcae.”',
 'if allowed things I ask, if give those walls the Fates.”',
 'if what I ask is allowed, if the Fates grant him those walls.”',
 "'Si concessa peto' is 'if I ask things granted', 'concessa' the perfect participle passive of 'concedo', 'allowed': she asks only for what the fates already allow. 'Dant ea moenia Parcae' is 'if the Fates give those walls', the walls of Rome, 'moenia' as object. 'Parcae' are the Fates, spinners of destiny. The closing mark ends Venus's speech."),
(799, 'alti:',
 'Then the Saturnian, tamer of the deep sea, uttered these things:',
 "Then Saturn's son, master of the deep sea, answered her thus:",
 "A new paragraph. 'Saturnius' is Neptune, 'son of Saturn' (brother of Jupiter and Juno); 'domitor maris alti' is 'tamer of the deep sea', a title. 'Haec… edidit' is 'uttered these things', 'edo' meaning 'bring forth', 'speak', with no 'inquit' needed. The colon leads to the speech, which runs to 815."),
(801, 'ducis:',
 '“Lawful it is, all of it, Cytherea, for you to trust in my realms,\nwhence your race you draw:',
 '“It is wholly right, Cytherea, that you trust my realms, from which you draw your descent:',
 "The opening mark begins Neptune's speech. 'Fas omne est' is 'it is entirely right' ('fas' what is permitted by divine law), with the infinitive 'te fidere' as its subject; 'fidere' is a verb of trusting that takes the dative, 'meis regnis'. 'Cytherea' is Venus, who came ashore at Cythera after her birth from the sea foam, so 'unde genus ducis' is 'from where you draw your lineage', her origin in the sea. The colon leads to the proof."),
(801, 'quoque;',
 'I have deserved it also;',
 'I have earned it too;',
 "'Merui' is a perfect, 'I have deserved', with 'quoque' 'also' and the object (that trust) understood: Neptune has done something to earn it. The semicolon runs on to the deeds in the next unit."),
(802, 'marisque.',
 'often the madnesses\nI have checked, and the rage so great of both sky and sea.',
 'Often I have checked the madness, the fierce rage of sky and sea alike.',
 "'Compressi' is the perfect of 'comprimo', 'press down', 'restrain'; 'furores' and 'rabiem tantam' are two objects, 'ragings' and 'so great a rage', and 'caelique marisque' (a double -que, 'both of sky and of sea') is a genitive depending on 'rabiem'. Neptune appeared in Book I, when he calmed the storm that Juno had sent (I.124ff), a scene this speech recalls."),
(804, 'tui.',
 'Nor less on the lands, Xanthus and Simois I call to witness,\nof Aeneas for me is care, of yours.',
 'Nor is my care for your Aeneas any less on land: I call Xanthus and Simois to witness.',
 "'Nec minor in terris… cura' is 'no less care on land', set against the sea where he is lord: 'est' left out; 'mihi' is a dative of possession, 'my care'. 'Xanthum Simoëntaque testor' is 'I call Xanthus and Simois to witness', two rivers of the Trojan plain, both in Greek-style accusatives, with the diaeresis (the two dots) marking the 'o' and 'e' of 'Simoëntaque' as separate syllables. 'Aeneae… tui' is an objective genitive after 'cura', 'care for your Aeneas', with the mother's claim in 'tui', 'your (son)'. The next sentence tells what he did on those banks."),
(805, 'muris,',
 'When Achilles,\nthe Trojan breathless columns pursuing, was driving them against the walls,',
 'When Achilles was pursuing the breathless Trojan ranks and driving them against the walls,',
 "The scene is the Iliad's: in book 21 Achilles drives the Trojans towards the city and the river, and the Xanthus (Scamander) is choked with the dead; in book 20 Poseidon, though he is on the Greek side, lifts Aeneas out of Achilles' way in a mist. 'Cum… impingeret' is a 'cum' clause with the imperfect subjunctive, a circumstance in the past (also 'daret', 'gemerent', 'posset'). 'Troia' is here the adjective, 'Trojan' (Troius, -a, -um), agreeing with 'agmina'; 'exanimata' is the perfect participle passive of 'exanimo', 'out of breath', 'terrified'. 'Sequens' is the present participle, 'pursuing'; 'impingeret agmina muris' is 'drove the ranks against the walls', 'muris' a dative."),
(808, 'Xanthus,',
 'many thousands he was giving to death, and groaned, filled\nthe rivers, nor to find a way and to roll out\ninto the sea could himself Xanthus,',
 'sent many thousands to death, and the rivers groaned, choked with them, and Xanthus could not find a way to roll himself out into the sea,',
 "'Milia multa' is 'many thousands', 'daret leto' 'was giving to death', 'leto' a dative. 'Gemerent repleti amnes' is 'the rivers groaned, filled up', 'repleti' agreeing with 'amnes' (a plural: the streams of the plain, the Xanthus above all); so full of bodies is it that the water can find no way to the sea (in Iliad 21 the Xanthus, choked with dead, rises against Achilles). 'Reperire viam atque evolvere… in mare se' is 'to find a way and to roll himself out into the sea', 'se' reflexive, 'posset' imperfect subjunctive after 'nec'. The unit stops after 'Xanthus' on a comma as the sentence is long."),
(810, 'rapui,',
 'to the son of Peleus, the strong, then I Aeneas\nhaving encountered, neither with gods nor strength equal,\nin a hollow cloud snatched,',
 'it was then that I snatched Aeneas, who had met the mighty son of Peleus with neither gods nor strength to match, away in a hollow cloud,',
 "'Pelidae… forti' is a dative with 'congressum', 'having met the strong son of Peleus', Achilles, 'Pelidae' a Greek patronymic dative; 'congressum' is the perfect participle of the deponent 'congredior', agreeing with 'Aenean' (Greek accusative). 'Nec dis nec viribus aequis' is 'neither with equal gods nor with equal strength', 'aequis' agreeing with both nouns: in Iliad 20 Aeneas, the weaker man, is saved only when Poseidon intervenes. 'Tunc ego' is the main clause, 'then I', 'rapui' 'snatched him away', 'nube cava' an ablative of means, 'in a hollow cloud' (Homer's 'mist'). 'Dis' is the dative-ablative plural of 'deus'; the Latin Library prints the same."),
(811, 'Troiae.',
 'though I wished to overturn from the bottom\nthe walls built by my hands of perjured Troy.',
 'though I longed to throw down from its foundations the walls of perjured Troy that my own hands had built.',
 "'Cuperem cum vertere' is 'although I wished to overturn', 'cum' concessive with the imperfect subjunctive: Neptune was Troy's enemy, since Laomedon, Priam's father, cheated him of his pay for building the walls (Iliad 21.441ff), hence 'periurae', 'perjured', 'faithless'. 'Ab imo' is 'from the bottom', 'from the foundations'; 'structa meis manibus' is 'built by my hands', 'structa' the perfect participle passive of 'struo', agreeing with 'moenia'. Even so he saved the man who would remake Troy."),
(812, 'timores.',
 'Now also the same mind stays with me: drive off your fears.',
 'Now too my mind is still the same: put your fears away.',
 "'Nunc quoque' is 'now also'; 'mens eadem perstat mihi' is 'the same mind persists for me', 'mihi' a dative of possession or reference. 'Pelle' is the imperative of 'pello', 'drive away'."),
(813, 'Averni.',
 'Safe, the harbours which you desire, he will reach, of Avernus.',
 'Safe, he will come to the harbour of Avernus that you long for.',
 "'Tutus' is predicative, 'safe', agreeing with the unexpressed subject, Aeneas. 'Portus… quos optas' is 'the harbours which you desire', the relative clause set inside the main one, 'quos' taking its plural from 'portus' (a plural for the single haven). 'Portus… Averni' is 'the harbour of Avernus', the volcanic lake near Cumae in Campania, with its cave and the Sibyl, the entrance to the underworld; Aeneas lands at Cumae at the start of Book VI. 'Accedet' is a future, 'will approach', and takes the accusative 'portus' directly, a poetic construction where prose would have 'ad'."),
(814, 'quaeres;',
 'One will be only, lost whom in the flood you will seek;',
 'There will be one only, whom you will look for, lost in the flood;',
 "'Unus erit tantum' is 'there will be only one'. 'Amissum quem gurgite quaeres' is a relative clause with 'amissum' ('lost') placed before its relative, 'quem… quaeres', 'whom you (Venus) will search for'; 'gurgite' is an ablative of place, 'in the flood'. The person is Palinurus, not yet named; the reader learns it a few lines later, and Aeneas meets his shade at VI.337."),
(815, 'caput.”',
 'one for many will be given, a head.”',
 'one life will be handed over for the sake of many.”',
 "A half-line: Virgil left it unfinished, and Greenough prints it short. 'Unum… caput' is 'one head', 'caput' standing for a person's life (as in 'capita' for a head-count), set against 'multis'. The closing mark ends Neptune's speech."),
(818, 'habenas.',
 'With these words when he had soothed the glad heart of the goddess,\nthe father yokes his horses with gold, and foaming adds\nbridles to the wild ones, and with his hands pours out all the reins.',
 "When with these words he had calmed the goddess's heart and made it glad, the father yokes his horses with gold, puts foaming bridles on the wild creatures, and lets all the reins run loose in his hands.",
 "A new paragraph. 'His… dictis' is an ablative of means, 'with these words'; 'ubi' with the perfect 'permulsit' is 'when he had soothed' (Neptune is the subject), 'laeta… pectora' 'her glad heart', a plural for the singular (you'll see this often). 'Genitor' is 'the father', an honorific for Neptune. 'Auro' is 'with gold', an ablative of means, either golden harness or golden yoke. 'Spumantia… frena' is 'foaming bits', 'feris' 'wild creatures', the dative, the sea-horses; 'omnes habenas effundit' is 'pours out all the reins', lets them run free. The Latin Library prints 'omnis' for 'omnes', the same case."),
(819, 'curru;',
 'On the sea-blue chariot light he flies over the topmost waters;',
 'Light on his sea-blue chariot he flies over the top of the water;',
 "'Caeruleo… curru' is 'on the dark blue chariot', an ablative of means, the colour of the sea, 'caeruleus', with 'curru' held to the end of the line; 'per summa… aequora' is 'over the topmost waters' ('summa' agrees with 'aequora'), 'levis' agreeing with the unexpressed 'he' ('light'). 'Volat' is 'flies', the vehicle skimming the waves, a scene with a Homeric model in Poseidon's drive over the sea at Iliad 13.23ff."),
(821, 'aquis;',
 'sink the waves, and the swollen, under the thundering axle,\nis laid flat the sea by the waters;',
 'the waves sink, and beneath the thundering axle the swollen sea lies flat, its waters smoothed;',
 "'Subsidunt' is 'settle', 'sink'. 'Tumidum… aequor' is 'the swollen sea', the subject of 'sternitur' ('is spread out', 'laid level'); 'aquis' is an ablative, probably of respect or manner ('as to its waters'), though some take it as the means: the point is that the swell lies flat. 'Tumidum… aequor' frames the clause. 'Sub axe tonanti' is 'under the thundering axle', 'tonanti' a present participle used as an adjective agreeing with 'axe': the axle thunders as the chariot passes, and the wave falls silent."),
(821, 'nimbi.',
 'flee from the vast sky the clouds.',
 'the clouds flee from the wide sky.',
 "'Fugiunt vasto aethere nimbi' is 'the rain clouds flee from the wide upper air', 'aethere' an ablative of separation (or of place, 'in the sky'). The three clauses of 819–821 make the calming of the storm, as in Book I (I.142ff, Neptune rides the waves and the clouds scatter)."),
(824, 'omnis;',
 "Then the various faces of the companions, huge sea-monsters,\nand the older chorus of Glaucus, and Ino's Palaemon,\nand the swift Tritons, and all the army of Phorcus;",
 "Then come the companions in their many shapes: huge sea-beasts, the aged band of Glaucus, Ino's son Palaemon, the quick Tritons, and all Phorcus's host;",
 "There is no verb in this list: 'there are' or 'come' is understood. 'Variae comitum facies' is 'the various shapes of his companions', the retinue of sea-folk. 'Immania cete' is 'huge sea-monsters', 'cete' a neuter plural (Greek). 'Senior Glauci chorus' is 'the aged choir of Glaucus' ('senior' 'older'), the fisherman of Anthedon who became a sea-god after eating a magic herb; 'Inousque Palaemon' is 'Ino's Palaemon', Melicertes, the son of Ino (Leucothea) who leapt into the sea with him and became the god of harbours. 'Tritones' are the sea-trumpeters, and 'Phorci exercitus' the host of Phorcus, an old sea-god father of the Graeae. 'Exercitus omnis' is 'the whole host'."),
(826, 'Cymodoceque.',
 'on the left hold Thetis, and Melite, and the maiden Panopea,\nNisaee, and Spio, and Thalia, and Cymodoce.',
 'On the left hand keep Thetis, Melite, the maiden Panopea, Nisaee, Spio, Thalia and Cymodoce.',
 "The 'laeva tenent' ('keep to the left') are the Nereids, daughters of the sea-god Nereus; the roll recalls the catalogue of Nereids in Iliad 18.39ff, which has several of these names (Thalia, Cymodoce, Nesaee, Spio, Melite, Panope). 'Tenent' is plural (the Latin Library prints 'tenet', singular). 'Laeva' is the neuter plural, 'the left-hand parts'. 'Panopeaque virgo' is 'and the maiden Panopea', 'Panopea' a Greek name. 'Nisaee' is the Nereid 'Nesaee', and 'Spio' ('Cave-dweller'); the list ends in a run of 'que'. The sea-procession ends the paragraph."),
(828, 'mentem:',
 'Here of father Aeneas the hanging, soothing, in turn\njoys test the mind:',
 'Then in their turn sweet joys work on the anxious mind of father Aeneas:',
 "A new paragraph. 'Hic' is 'here', 'at this', and 'vicissim' 'in turn', the joys answering the long suspense. 'Suspensam… mentem' is 'his hanging mind', 'in suspense'; 'pertemptant' is 'test', 'thrill through', and 'blanda gaudia' 'soothing joys', the subject. 'Patris Aeneae' is 'of father Aeneas', 'pater' a title."),
(829, 'velis.',
 'he bids at once all\nmasts to be raised, the yards to be stretched with sails.',
 'he orders all the masts raised at once and the yards spread with sails.',
 "'Iubet' takes two passive infinitives: 'attolli malos', 'intendi brachia velis', 'the yards (arms) to be spread with sails'. 'Ocius' is the comparative of 'cito', 'more quickly', 'at once'. The Latin Library prints 'omnis' for 'omnes', the same case. 'Brachia' is Greenough's spelling of 'bracchia', the arms of the yard (the Latin Library prints 'bracchia'); 'velis' is an ablative of means, 'with sails'. The subject of 'iubet' is Aeneas."),
(831, 'sinus;',
 'Together all they made the foot, and alike the left\nnow the right they loosed, the sails;',
 'All together they worked the sheets, and loosed the sails, now those on the left, now those on the right;',
 "'Una omnes' is 'all together'. 'Fecere' is a perfect in '-ere' for '-erunt' (you'll see this constantly). 'Pedem facere' is a sailor's phrase about handling the 'pes', the sheet (the rope at the lower corner of a sail); its exact sense is not settled (to haul it in, or to make it fast), but the picture is the crew working the sheets together. 'Pariterque sinistros… nunc dextros… sinus' has the adjectives before the noun: 'alike the left, now the right, folds of sail', the sails on one side and then the other eased as the wind requires. 'Solvere' is another '-ere' perfect, 'loosed', 'sinus' the belly or fold of a sail."),
(832, 'detorquentque;',
 'together the high yard-arms they turn\nand turn about;',
 'together they swing the lofty yard-arms about, then swing them back;',
 "'Ardua… cornua' are 'the high horns', the ends of the yard-arm, 'cornu' 'horn', 'the tip of the yard'; 'torquent… detorquentque' is 'twist and twist back', 'turn this way and that', a pair of opposed verbs joined by a single '-que' (not the double '-que… -que' of the pattern flagged earlier). 'Una' is 'together'."),
(832, 'classem.',
 'carry their own breezes the fleet.',
 'their own breezes carry the fleet.',
 "'Sua flamina' is 'their own breezes', 'flamina' a poetic word for winds ('flo', 'blow'); 'sua' looks back to the fleet, the object, 'the favouring winds that belong to them'. The fleet is now moving fast; the winds are the gift of Neptune's pledge."),
(834, 'agmen;',
 'First before all Palinurus was leading the close\nline;',
 'Palinurus led before them all, at the head of the close-packed line;',
 "'Princeps ante omnes' is 'first before all', 'princeps' predicative, 'as leader'. 'Densum… agmen' is 'the thick column', the close-packed ships, 'agebat' 'was leading' (an imperfect, setting a scene); the Latin Library prints 'omnis' for 'omnes', the same case. Palinurus is Aeneas's helmsman, who has appeared in Book III, here at the head as pilot of the lead ship."),
(834, 'iussi.',
 'to him the others their course to hold were ordered.',
 'the rest were told to keep their course by his.',
 "'Ad hunc… cursum contendere' is 'to hold their course by him', 'contendere' meaning 'strain', 'direct', so the rest of the fleet steers on his ship; 'iussi' is the perfect participle passive of 'iubeo', 'having been ordered', with 'sunt' left out. The rest of the fleet are to take their line from his ship."),
(836, 'contigerat;',
 'And now nearly the middle turning-post of the sky dewy Night\nhad touched;',
 'And now dewy Night had almost reached the mid turning-post of the sky;',
 "A new paragraph. 'Iamque fere' is 'and now almost', 'mediam… metam' 'the middle turning-post', the 'meta' being the post round which racing chariots turned (a picture from the games just described); Night has nearly reached the top of her course, midnight. 'Humida' is 'moist', 'dewy' (the Latin Library prints it without the 'h', 'umida'). 'Contigerat' is a pluperfect, 'had touched'. Night's half-way point is also in Anchises' words at V.738, 'Nox humida torquet medios cursus'."),
(837, 'nautae:',
 'in peaceful rest they were loosening their limbs,\nsprawled under the oars over the hard benches, the sailors:',
 'the sailors, stretched out on the hard benches beneath their oars, were easing their limbs in quiet rest:',
 "'Placida… quiete' is 'in calm rest', an ablative of manner, with 'laxabant membra' 'were loosening their limbs'. 'Sub remis fusi' is 'stretched out under the oars', 'fusi' from 'fundo', 'poured out'; 'per dura sedilia' 'over the hard seats', the rowers' benches. The 'nautae' is the subject, held to the end. The colon leads to 'cum', the sudden event, in the pattern 'iamque… cum' ('and now… when', the 'cum' with the indicative)."),
(839, 'umbras,',
 'when light from the heavenly stars gliding down Sleep\nthe dark air parted and dispersed the shadows,',
 'when Sleep, gliding lightly down from the heavenly stars, parted the dark air and scattered the shadows,',
 "'Cum' here is the inverted 'cum' of sudden event, 'when', with the perfect indicative 'dimovit' and 'dispulit' (not the imperfect subjunctive of circumstance). 'Levis' is 'light', 'delapsus' the perfect participle of the deponent 'delabor', 'having glided down'. 'Somnus' is Sleep as a god; he comes from 'aetheriis… astris', 'the heavenly stars'. In the Iliad (14.231ff) Hypnos (Sleep) helps Hera to put Zeus to sleep, and Virgil's god has a task of the same kind; he leaves in the shape of a bird at 861. 'Aëra' is the Greek accusative of 'aer', 'air', with the diaeresis (the Latin Library prints 'aera'); 'tenebrosum' is 'dark', and 'umbras' are 'shadows'."),
(841, 'insonti;',
 'you, Palinurus, seeking, to you dreams sad bringing,\nan innocent;',
 'heading for you, Palinurus, and bringing sad dreams to you, an innocent man;',
 "The address 'te, Palinure' is a sudden turn to the character (apostrophe), in which the narrator speaks to him as he goes to his death, a habit of Virgil's with characters he pities. 'Petens' is 'seeking', 'making for', 'portans' 'bringing', with 'te' and 'tibi' set against each other; 'somnia tristia' is 'sad dreams', 'insonti' a dative, 'to the innocent', 'harmless', who has done nothing to deserve it."),
(842, 'loquelas:',
 'and on the stern the god sat down, on the high one,\nlike Phorbas, and pours with his mouth these words:',
 'and the god took his seat on the high stern, in the likeness of Phorbas, and poured out from his mouth these words:',
 "'Puppi… in alta' is 'on the high stern', 'puppi' set before 'in alta' and its adjective, with 'consedit' 'sat down'. 'Phorbanti similis' is 'like Phorbas', 'similis' with the dative; Phorbas is a shipmate the poem tells nothing more of here, the god taking the shape of a familiar comrade whom Palinurus would trust (Phorbas is also a name in Homer). 'Funditque has ore loquelas' is 'pours these words from his mouth', 'loquelas' (from 'loquela') 'words', 'speech'. The colon leads to his speech, which runs to 846."),
(843, 'classem;',
 "“Iasus' son Palinurus, carry, themselves, the waters the fleet;",
 '“Palinurus, son of Iasus, the very waters carry the fleet;',
 "The opening mark begins the god's speech. 'Iaside' is the vocative of 'Iasides', 'son of Iasus', a Greek patronymic, with the name 'Palinure'. 'Ipsa aequora' is 'the very waters', 'the seas themselves', 'ferunt classem' 'bear the fleet'. The patronymic gives the helmsman a hero's dignity, as in Homer."),
(844, 'quieti.',
 'the breezes breathe steadily; the hour is given to rest.',
 'the breezes blow steadily; this is the hour that is given to rest.',
 "'Aequatae… aurae' is 'levelled breezes', winds even and without gusts; 'spirant' is 'blow'. 'Datur hora quieti' is 'an hour is given to rest', 'quieti' a dative of purpose. The two clauses are asyndeton, as are the short sentences of the speech, which give the god's sleepy, lulling tone."),
(845, 'labori:',
 'Lay down your head, and your weary eyes steal from labour:',
 'Lay your head down, and steal your tired eyes from their toil:',
 "'Pone caput' is 'put down your head', 'rest'. 'Furare' is the imperative of 'furor', 'steal', 'furare oculos labori' 'steal your eyes from toil', 'labori' a dative of separation after a verb of taking. 'Fessos' is 'tired'. The colon leads to the offer."),
(846, 'inibo.”',
 'I myself for a little while in your place your duties will take up.”',
 'I myself will take up your duties for a little while in your place.”',
 "'Ipse ego' is 'I myself'. 'Paulisper' is 'for a short time'; 'pro te' is 'in your place'; 'munera inibo' is 'I shall enter upon the duties', 'ineo' with 'munus', a formal phrase for undertaking an office. The closing mark ends the god's speech."),
(847, 'fatur:',
 'To him scarcely lifting his eyes Palinurus says:',
 'Palinurus, hardly lifting his eyes to him, answers:',
 "'Cui' is a connecting relative, 'to whom', 'to him'. 'Vix attollens… lumina' is 'scarcely raising his eyes', with the heavy eyelids of the tired man; 'fatur' is 'says', a deponent, solemn and old, and the colon leads to the helmsman's reply, which runs to 851."),
(849, 'iubes?',
 '“Me the face of the placid sea and the quiet waves\nto ignore do you bid?',
 '“Do you bid me ignore the face of the placid sea and its quiet waves?',
 "The opening mark begins Palinurus's reply. 'Mene… ignorare iubes?' is a question with the ordinary construction of 'iubeo', accusative and infinitive: 'me' (with the question particle '-ne') is the accusative and 'ignorare' the infinitive, 'do you tell me to ignore?', here 'to be blind to'. 'Salis placidi voltum' is 'the face of the quiet sea', 'sal' the salt, 'the sea', Greenough's spelling 'voltum' for 'vultum' (the Latin Library prints 'uultum'), 'fluctus quietos' 'the quiet waves'."),
(849, 'monstro?',
 'Me to this monster to trust?',
 'Am I to trust this monster?',
 "Another 'Mene' question, and this one is the accusative and infinitive of indignation (you saw it in 'Mene… desistere' in Book I): 'me… confidere' with the dative 'monstro', 'to this monster', with no verb of ordering needed. 'Monstrum' is a wonder or portent, an object of dread; the calm sea is the 'monster', harmless as it looks. 'Huic' is a single long syllable here."),
(851, 'sereni?”',
 'Aeneas shall I entrust (for why?) to deceitful breezes\nand to the sky, so often deceived by the fraud of the calm?”',
 'Am I to entrust Aeneas (for why?) to treacherous breezes and the sky, I who have so often been deceived by the fraud of a calm?”',
 "The print has 'credam quid enim' with no marks, where the sense needs '(quid enim?)', a dropped parenthesis; t keeps the print, because t must match the pinned source, and this unit therefore holds the whole question so that it ends at punctuation; l and i read the parenthesis. 'Credam' is a deliberative subjunctive, 'shall I entrust?', with 'Aenean' (a Greek accusative) as object; 'quid enim' is 'for why?', 'enim' giving the reason, a parenthetic question. 'Fallacibus auris et caelo' is a dative, 'to the deceitful breezes and the sky', the dative that 'credam' takes; 'totiens deceptus' is 'so often having been deceived', 'fraude sereni' 'by the treachery of the clear sky' (a calm that conceals a storm), 'sereni' a neuter adjective used as a noun, genitive. The Latin Library prints the genitive 'caeli' for Greenough's dative 'caelo'; Greenough's dative makes the sky a second thing not to be trusted. The closing mark ends Palinurus's reply."),
(853, 'tenebat.',
 'Such words he was giving, and the helm, fastened-to and clinging,\nnever was he letting go, and his eyes beneath the stars he was holding.',
 'So he spoke, and clinging fast to the tiller he never let it go, but kept his eyes on the stars.',
 "A new paragraph. 'Talia dicta dabat' is 'such words he was giving', a periphrasis for 'dixit'; the imperfects through the passage show a continuing effort against sleep. 'Clavum' is the object of 'amittebat', held back to the front of the clause; 'affixus et haerens' are nominatives agreeing with Palinurus, 'fastened and clinging' to it, 'clavus' the tiller, 'affixus' Greenough's spelling (the Latin Library prints 'adfixus'). 'Nusquam amittebat' is 'never let go', 'oculosque sub astra tenebat' 'held his eyes up to the stars', steering by them."),
(856, 'solvit.',
 'Look, the god a branch with Lethean dew dripping,\nand with Stygian power drugged, over both\ntemples shakes, and to the lingering the swimming eyes loosens.',
 'Then see, the god shakes over both his temples a bough dripping with the dew of Lethe and drugged with the power of the Styx, and as Palinurus struggles loosens his swimming eyes in sleep.',
 "'Ecce' is 'look', a sudden turn. 'Ramum Lethaeo rore madentem' is 'a branch wet with Lethean dew', 'Lethe' the river of forgetfulness in the underworld, 'rore' an ablative of means; 'vique soporatum Stygia' is 'drugged with the Stygian power', 'soporatum' the perfect participle passive of 'soporo', 'made sleepy', 'Stygia' the adjective 'of the Styx', agreeing with 'vi' (the Styx is another underworld river; sleep, as the brother of death, belongs to the dead). 'Super utraque tempora quassat' is 'shakes over both temples', 'utraque' 'each of the two'. 'Cunctanti' is a present participle in the dative, 'to him hesitating', 'resisting', and 'natantia lumina' 'swimming eyes'. The branch comes first in the sentence and the eyes last."),
(857, 'artus,',
 'Scarcely the first limbs unexpected rest had loosened,',
 'Hardly had unlooked-for rest begun to loosen his limbs,',
 "'Vix… laxaverat… et… proiecit' is the 'vix… cum' pattern with 'et' doing the work of 'cum': 'hardly had it loosened… and he threw him'. 'Quies' is the subject of the pluperfect 'laxaverat'; 'inopina' is 'unexpected', and 'primos artus' 'his first limbs', the limbs it first reached. Palinurus is not asleep yet when he is seized."),
(860, 'vocantem;',
 'and leaning over with part of the stern torn off,\nand with the helm, into the liquid waves he threw him\nheadlong, and his comrades in vain often calling;',
 'and, leaning over him, hurled him, with a piece of the stern torn away and the helm with it, headlong into the liquid waves, calling again and again to his comrades in vain;',
 "'Super incumbens' is 'leaning over', 'incumbo' with a god's weight, and the subject of 'proiecit' is the god; its object, Palinurus, is left unexpressed. 'Cum puppis parte revolsa cumque gubernaclo' is 'with a part of the stern torn off and with the rudder', 'revolsa' Greenough's spelling of 'revulsa' (the Latin Library prints 'reuulsa'), both 'cum's the preposition 'with', tying the wreckage to the man. 'Liquidas… in undas' is 'into the liquid waves'. 'Praecipitem' is 'headlong', and 'socios nequiquam saepe vocantem' 'calling his comrades often, in vain', both agreeing with the unexpressed object; the pathos is of a helmsman who cries out and is unheard."),
(861, 'auras.',
 'himself flying, up into the thin air he raised himself, a winged one.',
 'while the god himself soared up into the thin air on wings.',
 "'Ipse' is the god. 'Volans' is 'flying'; 'ales' is 'winged', used as a noun in apposition, 'as a winged creature' (as a bird). 'Se sustulit' is 'raised himself' ('tollo'), 'ad tenues… auras' 'to the thin breezes' (the Latin Library prints 'tenuis', the same accusative plural in another spelling). In Iliad 14.286ff Hypnos likewise takes bird shape, a clear-voiced night-bird in a pine."),
(863, 'fertur.',
 'Runs the way safe no less over the sea the fleet,\nand by the promises of father Neptune fearless is borne.',
 'The fleet runs on its way over the sea just as safely, carried fearlessly on the promises of father Neptune.',
 "'Non secius' is 'no less', 'not otherwise', Greenough's form (the Latin Library prints 'setius', the same word: 'secius' and 'setius' are variants). 'Iter tutum' is 'a safe way', an internal (cognate) accusative with 'currit', and 'aequore' 'over the sea'. 'Promissis… Neptuni' is an ablative of means or cause, 'by the promises of Neptune', the pledge of 813, and 'interrita' 'unafraid', the fleet not knowing what has happened. 'Fertur' is passive, 'is carried', and it contrasts with the helmsman who is lost."),
(866, 'sonabant:',
 'And now indeed to the rocks of the Sirens carried on it was approaching,\ndifficult once, and with the bones of many white,\nthen the hoarse with constant salt far off the rocks were sounding:',
 "And now it was drawing near to the Sirens' rocks, once so dangerous and white with the bones of many, as the rocks sounded hoarse far off with the constant salt sea:",
 "A new paragraph. 'Iamque adeo' is 'and now indeed', 'adeo' adding force; 'advecta' is the perfect participle passive of 'adveho', 'carried to', agreeing with 'classis' (understood from 863), and 'subibat' 'was approaching' (literally 'going up under'). 'Scopulos Sirenum' is 'the rocks of the Sirens', the bird-women of Odyssey 12 who lure sailors to death; the tradition put them on the islets off the Campanian coast (near Surrentum), and 'difficiles quondam', 'hard once', says that their danger is over. 'Multorumque ossibus albos' is 'white with the bones of many', 'ossibus' an ablative of cause. 'Tum' marks a second picture: 'rauca… saxa' 'the hoarse rocks', 'adsiduo… sale' 'with the constant salt (spray)', sounding 'longe', 'far off'. The Latin Library prints 'difficilis' for Greenough's 'difficiles', the same accusative plural. The colon leads to the 'cum' clause."),
(868, 'undis,',
 'when the father, his helmsman lost, drifting wandering\nfelt, and himself the ship in the night waves steered,',
 'when the father felt the ship wandering and adrift now that her helmsman was lost, and steered her himself over the night waves,',
 "'Cum' is again the inverted 'cum' (see 838). 'Pater' is Aeneas (as at 827). 'Amisso… magistro' is an ablative absolute, 'the pilot having been lost'; 'sensit' takes 'ratem' (next clause) with the participle 'fluitantem' ('drifting', 'fluito' a frequent form of 'fluo', 'float') and the infinitive 'errare' ('to wander'): 'felt the ship drifting, wandering'. 'Ratem' is the ship (literally a raft). 'Ipse' is Aeneas, steering it himself."),
(870, 'sereno,',
 "much groaning, and by his friend's fate shaken in mind\n“O too much in sky and sea serene trusting,",
 "with many a groan, and shaken in his heart by his friend's fate: “O you who put too much faith in a serene sky and sea,",
 "The print has 'amici' with no mark after it, where a colon belongs before the speech; t keeps the print, because t must match the pinned source, and this unit therefore runs on into the speech's first line so that it ends at punctuation; l and i supply the colon. No verb of speaking is printed; the reader supplies 'inquit' or 'dixit' (the ellipsis you see in 'haec secum'). 'Multa gemens' is 'groaning much', 'multa' an adverbial accusative. 'Casu… amici' is an ablative of cause, 'by the fall of his friend', 'concussus' the perfect participle passive of 'concutio', 'shaken'; 'animum' is an accusative of respect, 'in mind' (a Greek construction); 'amici' is Palinurus. The opening mark begins Aeneas's lament, 870–871, the last speech of the book. 'O nimium' is 'O too much', 'nimium' an adverb with 'confise'; 'confise' is a vocative of 'confisus', the perfect participle of the semi-deponent 'confido', 'having trusted', taking the ablative 'caelo et pelago sereno', 'in a clear sky and sea'. 'Sereno' agrees with 'pelago' and does for 'caelo' too. The reader knows that Palinurus had refused to trust the calm, and Aeneas speaks without knowing how he fell."),
(871, 'harena!”',
 'naked on an unknown, Palinurus, you will lie sand!”',
 'bare on sand you do not know, Palinurus, you will lie!”',
 "'Nudus' is 'bare', 'naked', and so unburied; 'in ignota… harena' is 'on an unknown sand', 'ignota' agreeing with 'harena', the ablative. 'Nudus' opens the line and 'harena' closes it, with the address 'Palinure' between them. 'Iacebis' is a future, 'you will lie'. The prophecy is fulfilled in VI.337ff, where Palinurus meets Aeneas as a shade and tells how he swam to the Italian coast and was killed there, his body left unburied. The closing mark ends Aeneas's speech and the book."),
]
P = A.part('aeneid-039'); L = A.lines_of(P); paras = {l['n'] for l in L if l['p']}
cuts = A.cut(P, [(u[0], u[1]) for u in U])
sents = []; prev_end_line = None
for (t, ln), (_, _t, l, i, n) in zip(cuts, U):
    u = {'t': t, 'l': l, 'i': i, 'n': n}
    if prev_end_line != ln and ln in paras: u['p'] = True
    u['v'] = True; u['ln'] = ln; sents.append(u)
    prev_end_line = ln + t.count('\n')
    if t.count('\n') != l.count('\n'): print('LINE COUNT', ln, repr(t[:30]), t.count('\n'), l.count('\n'))
    if t.count('\n') > 4: print('TOO LONG', ln)
    if '\n' in i: print('NEWLINE IN i', ln)
A.jdump({'title': TITLE, 'titleEn': TITLE_EN, 'part': PART, 'about': ABOUT, 'sentences': sents}, os.path.join(HERE, 'units.json'))
